import {createHash} from 'node:crypto';

// Machine state, never generated by the summarizer. Remains in this worker's
// memory; it is not a durable restart checkpoint or a mutation replay recipe.
export function createRunContinuity({getState,getProgress,activity,metrics}){
  let previous;
  const stats=metrics.continuity={checkpoints:0,unchangedCheckpoints:0};
  function snapshot(){return{kind:'run_continuity',version:1,...structuredClone(getState()),instruction:'Continue only unfinished steps. Recorded plans are not proof; verified checks and native receipts govern completion. Preserve original requirements and answers outside this packet. Failed/uncertain writes require receipt lookup and fresh observations, never blind replay. A context summary cannot approve or complete a step.'};}
  function checkpoint(){
    const state=snapshot(),key=createHash('sha256').update(JSON.stringify(getProgress?getProgress():{...state,lastFailure:undefined,lastFailures:undefined})).digest('hex'),unchanged=key===previous;previous=key;stats.checkpoints++;if(unchanged)stats.unchangedCheckpoints++;
    activity.note('현재 작업 상태를 정리하고 이어갑니다.','완료한 작업, 사용자 답변, 미해결 오류를 유지합니다.');return{state,unchanged};
  }
  return{snapshot,checkpoint};
}
